// Fork of "Slit Solitons" by wyatt. https://shadertoy.com/view/X33fDf
// 2025-01-25 15:45:23

Main {

    Q = 20.*A(U).yyyy;

    Q += sin(-1.+vec4(1,2,3,4)+400.*B(U)/float(iFrame));

}

Main {
    Q = A(U);
    vec4 n = A(U+vec2(0,1));
    vec4 e = A(U+vec2(1,0));
    vec4 s = A(U-vec2(0,1));
    vec4 w = A(U-vec2(1,0));
    vec4 m = 0.25*(n+e+s+w);
    Q.xz += (m-Q).yw-.5*Q.yw*((exp(-dot(Q.yw,Q.yw))));
    Q.yw += Q.xz;
    if (iMouse.z>0.) {
        Q.yw += 2.*sin(U.x+vec2(1,2))*exp(-length(U-iMouse.xy));

    }else {
        Q.yw += (0.5+0.5*sign(sin(iTime)-.8))*2.*
                sin(.8*U.x+vec2(1,2))*
                exp(-.3*length(U-vec2(.4,.5)*R));
    }
    if (abs(U.x-.5*R.x)<2.&&abs(U.y-.5*R.y)>.03*R.y) Q *= 0.;
    if (U.x < 10.||R.x-U.x<10.||U.y<10.||R.y-U.y<10.) Q *= .99;
    if (U.x<.5*R.x) Q *= .9999;
}

